//! INPUT constraint actions preserve actual native paint and editor/link state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn input_constraint_flags_actual_app_user_typing_paste_backspace_and_reenable(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-input-read-only-edit-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0}#area{position:absolute;left:20px;top:80px;width:180px;height:60px}#toggle{position:absolute;left:220px;top:20px;width:160px;height:32px}#check{position:absolute;left:420px;top:20px;width:160px;height:32px}</style><input id=area readonly value=Seed><button id=toggle type=button>Toggle read only</button><button id=check type=button>Check</button><script>var x=document.getElementById('area'),events=0;x.oninput=function(e){if(!e.isTrusted)throw 'trusted input';events++;};document.getElementById('toggle').onclick=function(e){if(!e.isTrusted)throw 'trusted toggle';x.readOnly=!x.readOnly;};document.getElementById('check').onclick=function(e){if(!e.isTrusted||!x.readOnly||x.value!=='XY'||x.defaultValue!=='Seed'||events!==2||x.getAttributeNS(null,'readonly')!=='')throw 'actual readonly editing';document.title='Readonly user editing checked';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let toggle=node(&app,"toggle");let check=node(&app,"check");
 fn click(app:&mut App,node:usize){let rect=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}
 click(&mut app,area);app.key(0x41,true,false,false);app.text_input('X');app.paste("Y");app.key(0x08,false,false,false);assert_eq!(app.forms.controls[&area].value.text(),"Seed");assert!(app.forms.controls[&area].readonly);
 click(&mut app,toggle);assert!(!app.forms.controls[&area].readonly);click(&mut app,area);app.key(0x41,true,false,false);app.text_input('X');app.paste("Y");assert_eq!(app.forms.controls[&area].value.text(),"XY");
 click(&mut app,toggle);assert!(app.forms.controls[&area].readonly);click(&mut app,area);app.key(0x41,true,false,false);app.text_input('Z');app.paste("Q");app.key(0x08,false,false,false);assert_eq!(app.forms.controls[&area].value.text(),"XY");click(&mut app,check);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Readonly user editing checked");
}

#[test]
fn input_constraint_flags_actual_app_validation_trusted_editing_post_paint_and_links(){let file=Fixture(std::env::temp_dir().join(format!("chezcat-input-constraint-flags-{}.html",std::process::id())));std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#cc2244}#paint.done{background:#2244cc}#paint.removed{background:#228844}#subject{position:absolute;left:20px;top:80px;width:150px;height:30px}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><div id=paint></div><form id=form method=post action=https://input-constraint-flags.test/submit><input id=subject name=q></form><input id=neighbor value=neighbor><button id=go type=button>Flags</button><a id=stable href=#destination>Go</a><div id=destination></div><script>var x=document.getElementById('subject'),round=0,events=0;x.oninput=function(e){if(!e.isTrusted)throw 'trusted edit';events++;};document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'trusted flags';x.required=round!==2;x.readOnly=round===1;var a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'required'),b=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'readOnly');if(a.get.call(x)!==(round!==2)||b.get.call(x)!==(round===1)||x.hasAttribute('required')!==(round!==2)||x.hasAttribute('readonly')!==(round===1)||x.value!==(round<3?'':'Y')||events!==(round<3?0:1))throw 'native flags';document.getElementById('paint').className=['ready','done','removed','ready'][round];document.title='Input constraint flags '+round;round++;};</script>"#).unwrap();let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let subject=node(&app,"subject");let go=node(&app,"go");let owner=node(&app,"form");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");fn click(app:&mut App,node:usize){let r=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let initial=app.draw();let mut selection=None;for round in 0..4{click(&mut app,go);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Input constraint flags {round}"));assert_eq!((app.forms.controls[&subject].required,app.forms.controls[&subject].readonly),(round!=2,round==1));if round==0{assert!(app.forms.submit_request(&app.document,owner,None,&app.location,&app.base_location).is_err());}else{assert!(app.forms.submit_request(&app.document,owner,None,&app.location,&app.base_location).is_ok());}if round==1||round==2{click(&mut app,subject);app.text_input(if round==1{'X'}else{'Y'});}assert_eq!(app.forms.controls[&subject].value.text(),if round<2{""}else{"Y"});if round>0{let request=app.forms.submit_request(&app.document,owner,None,&app.location,&app.base_location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};assert_eq!(body.as_slice(),if round==1{b"q=".as_slice()}else{b"q=Y".as_slice()});}let e=&app.forms.controls[&subject].value;if round==2{selection=Some((e.cursor,e.anchor,e.offset));}if round==3{assert_eq!(Some((e.cursor,e.anchor,e.offset)),selection);}let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844,0xcc2244][round]);if round==2{let r=app.page.controls.iter().find(|r|r.node==subject).unwrap();let(left,top,right,bottom)=(r.x.max(0)as usize,(app.content_top()+r.y-app.scroll).max(0)as usize,(r.x+r.width).min(painted.width as i32)as usize,(app.content_top()+r.y-app.scroll+r.height).min(painted.height as i32)as usize);assert!(left<right&&top<bottom);assert!((top..bottom).any(|y|initial.pixels[y*initial.width+left..y*initial.width+right]!=painted.pixels[y*painted.width+left..y*painted.width+right]));}let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),(raw.clone(),location.clone(),epoch));}}
